 Future<void>refreshMe()async{try{final j=await widget.api.get('/me');if(mounted)setState(()=>me=Map<String,dynamic>.from(j['user'] as Map));}catch(e){if(mounted)errorToast(context,e);}}
 Future<void>_incoming()async{
  if(incomingDialog||!mounted||!(ModalRoute.of(context)?.isCurrent??false))return;
  try{
   final j=await widget.api.get('/calls/incoming');final calls=j['calls'] as List;
   if(calls.isEmpty||!mounted)return;
   incomingDialog=true;final item=Map<String,dynamic>.from(calls.first as Map);
   final accept=await showDialog<bool>(context:context,barrierDismissible:false,builder:(d)=>AlertDialog(title:const Text('Incoming video call'),content:Text('${item['caller_name']} is calling you'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Decline')),ElevatedButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Accept'))]));
