   await widget.api.post('/calls/${item['id']}/answer',{'accept':accept==true});
   if(accept==true&&mounted)await Navigator.push(context,MaterialPageRoute(builder:(_)=>VideoRoomScreen(api:widget.api,title:'Private video call',tokenEndpoint:'/calls/${item['id']}/token',callId:'${item['id']}')));
  }catch(e){if(mounted)errorToast(context,e);}finally{incomingDialog=false;}
 }
 @override Widget build(BuildContext context){
  final user=me??<String,dynamic>{};
  final screens=<Widget>[PeoplePage(api:widget.api,myId:'${user['id']??''}'),LivePage(api:widget.api,me:user),InboxPage(api:widget.api),WalletPage(api:widget.api),ProfilePage(api:widget.api,me:user,refresh:refreshMe,onLogout:widget.onLogout)];
  return Scaffold(appBar:AppBar(title:Row(children:[const Icon(Icons.auto_awesome,color:cyan),const SizedBox(width:8),const Text('NovaLive',style:TextStyle(fontWeight:FontWeight.bold))]),actions:[IconButton(tooltip:'Refresh',onPressed:()=>setState((){refreshMe();}),icon:const Icon(Icons.refresh)),const SizedBox(width:8)]),body:IndexedStack(index:selected,children:screens),bottomNavigationBar:NavigationBar(backgroundColor:panel,selectedIndex:selected,onDestinationSelected:(n){setState(()=>selected=n);if(n==3||n==4)refreshMe();},destinations:const [NavigationDestination(icon:Icon(Icons.explore_outlined),selectedIcon:Icon(Icons.explore),label:'Discover'),NavigationDestination(icon:Icon(Icons.live_tv_outlined),selectedIcon:Icon(Icons.live_tv),label:'Live'),NavigationDestination(icon:Icon(Icons.chat_bubble_outline),selectedIcon:Icon(Icons.chat),label:'Chats'),NavigationDestination(icon:Icon(Icons.account_balance_wallet_outlined),selectedIcon:Icon(Icons.account_balance_wallet),label:'Wallet'),NavigationDestination(icon:Icon(Icons.person_outline),selectedIcon:Icon(Icons.person),label:'Me')]));
 }
}
