class OutgoingCallScreen extends StatefulWidget{final Api api;final String callId,person;const OutgoingCallScreen({super.key,required this.api,required this.callId,required this.person});@override State<OutgoingCallScreen>createState()=>_OutgoingCallScreenState();}
class _OutgoingCallScreenState extends State<OutgoingCallScreen>{Timer? timer;bool finished=false;
 @override void initState(){super.initState();timer=Timer.periodic(const Duration(seconds:2),(_)=>check());check();}
 Future<void>check()async{if(finished)return;try{final j=await widget.api.get('/calls/outgoing/${widget.callId}');final status='${j['call']['status']}';if(status=='accepted'){finished=true;timer?.cancel();if(mounted){await Navigator.push(context,MaterialPageRoute(builder:(_)=>VideoRoomScreen(api:widget.api,title:widget.person,tokenEndpoint:'/calls/${widget.callId}/token',callId:widget.callId)));if(mounted)Navigator.pop(context);}}else if(status=='rejected'||status=='ended'){finished=true;timer?.cancel();if(mounted){errorToast(context,'Call $status');Navigator.pop(context);}}}catch(e){if(mounted)errorToast(context,e);}}
 Future<void>cancel()async{if(finished)return;finished=true;timer?.cancel();await widget.api.post('/calls/${widget.callId}/end',{}).catchError((_){return <String,dynamic>{};});if(mounted)Navigator.pop(context);}
 @override void dispose(){timer?.cancel();super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[gradientAvatar(widget.person,size:110),const SizedBox(height:28),Text(widget.person,style:const TextStyle(fontSize:28,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Ringing... waiting for acceptance',style:TextStyle(color:Colors.white60)),const SizedBox(height:40),ElevatedButton.icon(style:ElevatedButton.styleFrom(backgroundColor:Colors.red),onPressed:cancel,icon:const Icon(Icons.call_end),label:const Text('Cancel call'))]))));
}
