class ProfilePage extends StatelessWidget{final Api api;final Map<String,dynamic>me;final Future<void> Function() refresh,onLogout;const ProfilePage({super.key,required this.api,required this.me,required this.refresh,required this.onLogout});
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(18),children:[sectionHeading('My profile','Account & safety settings'),Center(child:gradientAvatar('${me['name']??'N'}',size:102)),const SizedBox(height:16),Center(child:Text('${me['name']??'User'}',style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold))),Center(child:Text('${me['email']??''}',style:const TextStyle(color:Colors.white60))),const SizedBox(height:8),Center(child:Chip(label:Text('${me['role']??'user'}'.toUpperCase()))),const SizedBox(height:22),Card(child:Column(children:[ListTile(leading:const Icon(Icons.edit),title:const Text('Edit profile'),trailing:const Icon(Icons.chevron_right),onTap:()=>edit(context)),const Divider(height:1),const ListTile(leading:Icon(Icons.verified_user),title:Text('Account security'),subtitle:Text('Never share your password or session credentials.')),const Divider(height:1),const ListTile(leading:Icon(Icons.privacy_tip),title:Text('Privacy & safety'),subtitle:Text('Use report and block controls on member cards.'))])),const SizedBox(height:22),fullButton('Log out',()=>onLogout(),icon:Icons.logout)]);
 Future<void>edit(BuildContext context)async{final name=TextEditingController(text:'${me['name']??''}'),bio=TextEditingController(text:'${me['bio']??''}');final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Edit your profile'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Name')),const SizedBox(height:12),TextField(controller:bio,maxLength:400,decoration:const InputDecoration(labelText:'About you'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),ElevatedButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(ok==true){try{await api.patch('/me',{'name':name.text,'bio':bio.text});await refresh();}catch(e){if(context.mounted)errorToast(context,e);}}name.dispose();bio.dispose();}
